const A=window.AtomApp;const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let msg='',loaded=false,store={},saving=false;function notice(){return '<div class="status" role="status">'+esc(msg)+(loaded?'':' <button id="retry-load">重试读取</button>')+'</div>'}function wire(){if($('retry-load'))$('retry-load').onclick=()=>readStore();}async function readStore(){if(A)A.deferReady();try{store=A?await A.load(DEFAULT):JSON.parse(JSON.stringify(DEFAULT));if(!store||typeof store!=='object')throw Error();loaded=true;msg='';afterLoad();}catch(e){loaded=false;msg='读取失败，未覆盖已有记录';render()}finally{if(A)A.ready()}}async function saveStore(next){if(!loaded||saving)return false;saving=true;msg='正在保存…';render();try{if(!A)throw Error();await A.save(next);store=next;msg='已保存';return true}catch(e){msg='保存失败，请重试';return false}finally{saving=false;render()}}function setBack(fn){if(A)AtomApp.navigation.setBackHandler(fn)}function home(){if(A)A.home()}function afterLoad(){render()}if(A)A.onSuspend(()=>{document.getAnimations().forEach(x=>x.cancel());suspend()});function suspend(){}
const DEFAULT={letters:{}};let offset=0,writing=false,draft='';const phases=['新月','娥眉月','上弦月','盈凸月','满月','亏凸月','下弦月','残月'];
function day(){let d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+offset);return d}function dateKey(){let d=day();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function moon(){let d=SunCalc.getMoonIllumination(day()),phase=d.phase,lit=d.fraction;let cut=Math.abs(1-2*lit)*78,side=phase<.5?1:-1;return {phase,lit,svg:'<svg viewBox="0 0 210 210"><defs><radialGradient id="m"><stop stop-color="#e8e6e0"/><stop offset=".75" stop-color="#b9c0cf"/><stop offset="1" stop-color="#8492b1"/></radialGradient><filter id="g"><feGaussianBlur stdDeviation="14"/></filter><clipPath id="disk"><circle cx="105" cy="105" r="78"/></clipPath></defs><circle cx="105" cy="105" r="90" fill="#5266aa" opacity=".2" filter="url(#g)"/><circle cx="105" cy="105" r="78" fill="url(#m)"/><g clip-path="url(#disk)" opacity=".16">'+Array.from({length:19},(_,i)=>'<circle cx="'+(46+i*53%120)+'" cy="'+(39+i*31%130)+'" r="'+(3+i%5*2)+'" fill="#465371"/>').join('')+'</g><path d="M105 27 A78 78 0 0 '+(side>0?0:1)+' 105 183 A'+Math.max(.1,cut)+' 78 0 0 '+((lit<.5)===(side>0)?0:1)+' 105 27" fill="#121c35" opacity=".93"/></svg>'}}
function render(){let key=dateKey(),m=moon();if(writing){$('screen').innerHTML='<div class="editor"><span class="eyebrow">'+key+' · 月光手记</span><textarea id="letter" aria-label="给今天留一句话" maxlength="300" placeholder="长按摇杆，把今天留在这里">'+esc(draft)+'</textarea><p class="muted">只保存在当前设备，最多保留最近 60 天。</p></div><div class="actions"><button id="save" '+(!loaded||saving?'disabled':'')+'>保存来信</button><button id="cancel">取消</button></div>'+notice();$('letter').oninput=e=>draft=e.target.value;$('save').onclick=async()=>{let letters=Object.assign({},store.letters||{},{[key]:draft});let keys=Object.keys(letters).sort();keys.slice(0,Math.max(0,keys.length-60)).forEach(k=>delete letters[k]);if(await saveStore({letters})){writing=false;render()}};$('cancel').onclick=()=>{writing=false;render()};}else{$('screen').innerHTML='<div class="columns"><div class="art">'+m.svg+'</div><div class="copy"><span class="eyebrow">'+key+'</span><h2>'+phases[Math.floor(m.phase*8+.5)%8]+'</h2><p class="muted">照亮 '+Math.round(m.lit*100)+'%<br>距下次满月约 '+Math.ceil(((.5-m.phase+1)%1)*29.53059)+' 天</p><p class="letter-preview">'+esc((store.letters||{})[key]||'今天，月亮也在这里。')+'</p></div></div><div class="actions"><button id="prev">前一天</button><button id="write" '+(!loaded?'disabled':'')+'>写封来信</button><button id="next">后一天</button></div><div class="foot">月相近似计算 · SunCalc</div>'+notice();$('prev').onclick=()=>{offset--;render()};$('next').onclick=()=>{offset++;render()};$('write').onclick=()=>{draft=(store.letters||{})[key]||'';writing=true;render()};}wire()}
setBack(()=>{if(writing){writing=false;render()}else home()});render();readStore();
